# AUTO-GENERATED by _add_daily_fortune.py + Step 3 variation seed
"""
일운 API — 구독자 전용 + Seed 기반 변형.

Gating:
- 인증 필수 (401)
- tier in ('subscription', 'premium') → 200
- 그 외 → 403
"""
import logging
from datetime import date, datetime
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from fastapi import APIRouter, Depends, HTTPException

from app.engine.calculator import calculate_saju
from app.engine.daily_fortune import calculate_daily_range
from app.engine.yongsin import derive_useful_god
from app.semantic.tagger import _extract_pillars
from app.services.daily_writer import write_daily_section
from app.auth.dependencies import get_current_user
from app.schemas.daily import DailyRequest, DailyResponse


logger = logging.getLogger(__name__)
router = APIRouter()

_PAID_TIERS = ("subscription", "premium")


def _resolve_today(tz_str: str) -> date:
    try:
        tz = ZoneInfo(tz_str)
    except (ZoneInfoNotFoundError, ValueError):
        tz = ZoneInfo("Asia/Seoul")
    return datetime.now(tz).date()


@router.post("/daily", response_model=DailyResponse)
def api_daily(
    payload: DailyRequest,
    user: dict = Depends(get_current_user),
):
    logger.info(f"[Daily API] user={user.get('id')} tier={user.get('tier')}")

    if user.get("tier") not in _PAID_TIERS:
        raise HTTPException(
            status_code=403,
            detail=(
                "Daily fortune is available on subscription or premium tiers. "
                "Upgrade from the app's plans screen."
            ),
        )

    try:
        result = calculate_saju(
            birth_date=payload.birth_date,
            birth_time=payload.birth_time,
            birth_time_mode=payload.birth_time_mode,
            timezone_str=payload.timezone_str,
            longitude=payload.longitude,
            correction_mode=payload.correction_mode,
            jasi_boundary=payload.jasi_boundary,
            gender=payload.gender,
            dst_fold=payload.dst_fold,
            birth_location=payload.birth_location,
        )
        pillars = _extract_pillars(result)
        day_stem = pillars["day_pillar"][0]
        yongsin = derive_useful_god(pillars)
    except (ValueError, TypeError) as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception:
        logger.exception("Daily calculation failed")
        raise HTTPException(status_code=500, detail="Calculation error.")

    start = (
        date.fromisoformat(payload.target_date)
        if payload.target_date
        else _resolve_today(payload.timezone_str)
    )
    daily_raw = calculate_daily_range(start, payload.days, day_stem, yongsin)

    # Step 3: variation seed — 유저 ID 우선, 없으면 birth_date
    response = write_daily_section(
        daily_raw,
        lang=payload.lang,
        user_id=user.get("id"),
        birth_date=payload.birth_date,
    )
    return {"daily": response}
